import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.DaAXJYxM.js";const m=JSON.parse('{"title":"第28章 根本不算","description":"","frontmatter":{},"headers":[],"relativePath":"第28章_根本不算.md","filePath":"第28章_根本不算.md"}'),r={name:"第28章_根本不算.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第28章-根本不算" tabindex="-1">第28章 根本不算 <a class="header-anchor" href="#第28章-根本不算" aria-label="Permalink to &quot;第28章 根本不算&quot;">​</a></h1><p>十二月初，她忽然问了我一句话。</p><p>那天是周五晚上。我们照例在零点之后说话，她讲了一堆学校里的事，讲她们班要排练一个节目，讲她今天中午吃了一个很难吃的菜。</p><p>说到一半，她停了。</p><p>过了一会儿，她发来一句。</p><p>她说：你最近是不是有点累。</p><p>我说：还行。</p><p>她说：你说还行就是累。</p><p>我说：真还行。</p><p>她说：你成绩掉了。</p><p>我说：没掉多少。</p><p>她说：我看了排名表。</p><p>我说：你怎么看的。</p><p>她说：公告栏上贴着。</p><p>我没说话。我们学校每次月考之后会在公告栏上贴前一百名的名单。我在名单里，但这次从五十几名滑到了第八十几。</p><p>她说：是不是因为我。</p><p>我说：不是。</p><p>她说：你别撒谎。</p><p>我说：真不是，我最近玩手机玩多了。</p><p>她说：那你别玩了。</p><p>我说：好。</p><p>隔了一会儿，她说：我有时候会想一件事。</p><p>我说：什么事。</p><p>她说：我觉得我在拖你。</p><p>那句话让我在被子里躺了很久。</p><p>我说：你没有。</p><p>她说：你别说没有，你先听完。</p><p>她说：你本来在南雾读得好好的，你非要过来。</p><p>她说：你过来之后，我们又不能见面，又不能说，我给你的东西还不够你麻烦的。</p><p>她说：我在想，也许我们这样，根本就不算是喜欢。</p><p>我盯着这句话看了很久。</p><p>如果我再聪明一点，我这时候就该说不是。</p><p>可我那时候太想讲道理了。</p><p>我打了一段话，那段话大概是这个意思：我说不能这么算，我过来是我自己的决定，跟她没关系；我说我们现在的困难是暂时的，等毕业就好了；我说感情不是讲划不划算的事。</p><p>我打了两段，删掉，又打，最后发出去的是这一句：</p><p>「你别想那么多，这些都是外面的事。」</p><p>发出去之后我就知道错了。</p><p>她很久没回。</p><p>久到我开始怀疑自己是不是把话说得太过了。我又补了一条：我不是说你多想，我是说你不用把它当负担。</p><p>还是没回。</p><p>过了大概二十分钟，她回了一句。</p><p>她说：哦。</p><p>就一个字。</p><p>我说：你是不是生气了。</p><p>她说：没有。</p><p>我说：那你说话。</p><p>她说：我在收拾东西。</p><p>我说：这么晚收拾什么。</p><p>她说：不关你的事。</p><p>那天晚上就停在这里。她下线了，比我早。</p><p>第二天她没有消息。</p><p>第三天也没有。</p><p>第四天早上，我给她发了一条：你是不是在生我的气。</p><p>她过了几个小时才回。</p><p>她说：我不是生气。</p><p>她说：我就是觉得，你听不懂我说话。</p><p>我看着这句话，心里有点凉。我不知道该怎么回。</p><p>她又发来一条。</p><p>她说：你上次问我为什么让你叫那个名字。</p><p>我说：嗯。</p><p>她说：你现在还不明白。</p><p>我说：那你告诉我。</p><p>她说：我不告诉你。</p><p>她说：你要是明白，你早就明白了。</p><p>那几天我们之间很安静。</p><p>她不是不理我，她照旧上线，照旧说话，照旧讲她班里的事。可我能感觉到一件事：她把话收起来了。</p><p>她以前会说的事，现在不说了。她以前会问我的问题，现在不问了。她回我的字越来越短，中间的空越来越长。</p><p>我那时候还不明白，她其实是在给我一个机会。她在等我主动去问，等我主动去说那句我不敢说的话。</p><p>可我一直没有。</p><p>我只是每天照旧发消息，照旧问她吃没吃饭，照旧在她上线的时候守着。我以为守住了就够了。</p><p>第六天晚上，她发来一句。</p><p>她说：我明天要回家。</p><p>我说：回家干嘛。</p><p>她说：我奶奶身体不好。</p><p>我说：要不要紧。</p><p>她说：不知道。</p><p>我说：那你去吧。</p><p>她说：嗯。</p><p>隔了一会儿，她说：我不确定什么时候回来。</p><p>我说：你几号回。</p><p>她说：不知道。</p><p>我说：那你把号码给我，我给你打电话。</p><p>她说：不用。</p><p>我说：那你怎么联系我。</p><p>她说：我到了会告诉你。</p><p>我说：好。</p><p>她说：你别老说好。</p><p>我没回。</p><p>那天晚上她走的时候，我们之间连一句再见都没有。</p><p>她走了四天。</p><p>那四天我照常上课，照常做题，照常在食堂吃饭。可我发现我做什么都提不起劲。</p><p>我甚至不太能集中注意力。数学课上一次我把一道题看错了两遍，把“不等式”看成“等式”，结果整道题都做反了。</p><p>那几天我没走西边那条走廊，也没去天井。我觉得没意思。</p><p>第三天晚上，沈聿拉我去操场跑步。他说我最近跟泥一样。</p><p>我们跑了五圈。我很久没运动，跑到第三圈腿就软了。沈聿在旁边跑，一边跑一边说话，说他们家里的事，说他初中的事。他说了一路。</p><p>跑完我们在操场边上坐着。他递给我一瓶水。</p><p>他说，你现在能说了吗。</p><p>我说，说什么。</p><p>他说，你到底为什么来这儿。</p><p>那天晚上我第一次把这件事跟人说了。</p><p>没说很多，就几句话。我说我在南雾认识一个人，我们认识很久了，我来到这边，是因为她在这里。</p><p>沈聿听完，沉默了一会儿。</p><p>他说，那你见到她了吗。</p><p>我说，见到了。</p><p>他说，怎么样。</p><p>我说，不怎么样。</p><p>他说，那你还留着干嘛。</p><p>我没回答。</p><p>那天晚上我回宿舍，躺到床上，想起沈聿那句话。</p><p>我那时候不敢想的其实是另一句话：如果她真的问我“我们这样算不算喜欢”，我应该怎么答。</p><p>那四天里我想了很多次。吃饭的时候想，走路的时候想。我想过很多种回答，每一种都比当时说的那一句好。</p><p>第五天中午，她来了。</p><p>她说：我回来了。</p><p>我说：你奶奶怎么样。</p><p>她说：还行。</p><p>她说：我在车上想了一路。</p><p>我问：想什么。</p><p>她说：想那天的事。</p><p>她说：我说的那些话，你别往心里去。</p><p>我说：我没往心里去。</p><p>她说：你看你又来了。</p><p>她停了一会儿，发来一句。</p><p>她说：那你告诉我，你是不是没听懂。</p><p>我说：我听懂了。</p><p>她说：那你为什么那么说。</p><p>我说：因为我怕说错了。</p><p>她过了一会儿回。</p><p>她说：你怕什么。</p><p>我说：我怕说了你就不理我了。</p><p>她说：你现在不也一样不理我。</p>',130)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
